import { useState, useEffect } from 'react';
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : initialValue;
  });
  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);
  return [value, setValue] as const;
}

import express, { Request, Response } from 'express';
import multer from 'multer';
import pdfParse from 'pdf-parse';

const upload = multer({ storage: multer.memoryStorage() });
const router = express.Router();

interface ScanRequestQuery {
  jobDescription: string;
}

router.post('/scan', upload.single('resume'), async (req: Request, res: Response): Promise<void> => {
  try {
    if (!req.file) {
      res.status(400).json({ error: 'No resume PDF uploaded' });
      return;
    }

    const jobDescription = req.body.jobDescription || '';
    if (!jobDescription) {
      res.status(400).json({ error: 'Job description is required' });
      return;
    }

    // Parse PDF buffer
    const pdfData = await pdfParse(req.file.buffer);
    const resumeText = pdfData.text.toLowerCase();

    // Tokenize and clean job description for keywords
    const stopWords = new Set(['and', 'the', 'to', 'a', 'of', 'in', 'for', 'is', 'on', 'with', 'an']);
    const jdWords = jobDescription
      .toLowerCase()
      .replace(/[^\w\s]/gi, '')
      .split(/\s+/
      );

    const uniqueKeywords = Array.from(new Set(jdWords)).filter(
      (word) => word.length > 2 && !stopWords.has(word)
    );

    const matchedKeywords: string[] = [];
    const missingKeywords: string[] = [];

    uniqueKeywords.forEach((keyword) => {
      if (resumeText.includes(keyword)) {
        matchedKeywords.push(keyword);
      } else {
        missingKeywords.push(keyword);
      }
    });

    const totalKeywords = uniqueKeywords.length;
    const matchScore = totalKeywords > 0 ? Math.round((matchedKeywords.length / totalKeywords) * 100) : 0;

    res.json({
      matchScore,
      matchedKeywords,
      missingKeywords,
      totalKeywordsChecked: totalKeywords,
    });
  } catch (error) {
    console.error('Scan error:', error);
    res.status(500).json({ error: 'Failed to parse PDF or calculate score' });
  }
});

export default router;

import React, { useState } from 'react';

interface ScanResult {
  matchScore: number;
  matchedKeywords: string[];
  missingKeywords: string[];
  totalKeywordsChecked: number;
}

export const MatchScoreDashboard: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [jobDescription, setJobDescription] = useState<string>('');
  const [loading, setLoading] = useState<boolean>(false);
  const [result, setResult] = useState<ScanResult | null>(null);

  const handleScan = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!file || !jobDescription) return;

    setLoading(true);
    const formData = new FormData();
    formData.append('resume', file);
    formData.append('jobDescription', jobDescription);

    try {
      const res = await fetch('/api/scan', {
        method: 'POST',
        body: formData,
      });
      const data = await res.json();
      setResult(data);
    } catch (err) {
      console.error('Error scanning resume:', err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto p-6 bg-slate-900 text-slate-100 rounded-xl shadow-2xl">
      <h1 className="text-3xl font-bold mb-6 text-indigo-400">AI Resume Keyword Scanner</h1>
      <form onSubmit={handleScan} className="space-y-6">
        <div>
          <label className="block text-sm font-medium mb-2">Job Description</label>
          <textarea
            rows={5}
            className="w-full p-3 bg-slate-800 border border-slate-700 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none"
            placeholder="Paste job description here..."
            value={jobDescription}
            onChange={(e) => setJobDescription(e.target.value)}
          />
        </div>
        <div>
          <label className="block text-sm font-medium mb-2">Upload Resume (PDF)</label>
          <input
            type="file"
            accept=".pdf"
            onChange={(e) => e.target.files && setFile(e.target.files[0])}
            className="w-full text-sm text-slate-400 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-indigo-600 file:text-white hover:file:bg-indigo-700 cursor-pointer"
          />
        </div>
        <button
          type="submit"
          disabled={loading || !file || !jobDescription}
          className="w-full py-3 bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-700 rounded-lg font-semibold transition-all shadow-lg"
        >
          {loading ? 'Analyzing Resume...' : 'Scan & Calculate Match Score'}
        </button>
      </form>

      {result && (
        <div className="mt-10 grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="col-span-1 bg-slate-800 p-6 rounded-xl flex flex-col items-center justify-center border border-slate-700">
            <div className="text-5xl font-extrabold text-indigo-400 mb-2">{result.matchScore}%</div>
            <div className="text-sm text-slate-400 uppercase tracking-wider">Match Score</div>
          </div>
          <div className="col-span-2 bg-slate-800 p-6 rounded-xl border border-slate-700 space-y-4">
            <div>
              <h3 className="text-sm font-semibold text-emerald-400 mb-2">Matched Keywords</h3>
              <div className="flex flex-wrap gap-2">
                {result.matchedKeywords.map((kw, i) => (
                  <span key={i} className="px-3 py-1 bg-emerald-950 text-emerald-300 border border-emerald-800 rounded-full text-xs font-medium">
                    {kw}
                  </span>
                ))}
              </div>
            </div>
            <div>
              <h3 className="text-sm font-semibold text-rose-400 mb-2">Missing Keywords</h3>
              <div className="flex flex-wrap gap-2">
                {result.missingKeywords.map((kw, i) => (
                  <span key={i} className="px-3 py-1 bg-rose-950 text-rose-300 border border-rose-800 rounded-full text-xs font-medium">
                    {kw}
                  </span>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};
